import{_ as p,c as t,d as s,b as e,r as o,o as c}from"./app-BhQmNbsN.js";const l={};function i(u,n){const a=o("Mermaid");return c(),t("div",null,[n[0]||(n[0]=s('<h1 id="gowind-admin-拆解-bi-大屏设计器——可序列化-schema、resolver-取数与版本快照" tabindex="-1"><a class="header-anchor" href="#gowind-admin-拆解-bi-大屏设计器——可序列化-schema、resolver-取数与版本快照"><span>GoWind Admin 拆解：BI 大屏设计器——可序列化 schema、resolver 取数与版本快照</span></a></h1><blockquote><p>本文回答一个问题：<strong>把可视化设计器接进中后台时，schema 如何同时约束设计器与渲染器、取数如何不焊死在图表组件里、整份覆盖保存又怎样避免互相踩踏？</strong></p></blockquote><p>BI 模块的产品形态可以压缩成一句话：一块可拖拽的仪表盘/大屏、一份描述它的 JSON，以及围绕这份 JSON 的存取与版本管理。真正难的不是把 ECharts 画出来，而是三条边界：</p><ul><li><strong>schema 与运行时</strong>：JSON 里不能有函数，取数与事件必须从外部注入；</li><li><strong>内核与宿主</strong>：图型、布局、主题、撤销栈归组件库，持久化、权限、租户归中后台；</li><li><strong>保存与并发</strong>：整份覆盖保存天然会互相踩踏，版本号与快照要把这条路收窄。</li></ul><p>下面按「边界 → schema → 数据 → 渲染 → 设计器 → 持久化 → 三端接入 → 失败模式」的顺序拆。</p><h2 id="一、边界-payload-是黑盒-宿主只负责存取" tabindex="-1"><a class="header-anchor" href="#一、边界-payload-是黑盒-宿主只负责存取"><span>一、边界：payload 是黑盒，宿主只负责存取</span></a></h2><p>架构上分两层：<code>@go-wind/bi-*</code> 负责「图怎么画、怎么改」，go-wind-admin 负责「图存在哪、谁能改、改了几版」。</p>',7)),e(a,{code:""}),n[1]||(n[1]=s(`<p>这个边界在 ent schema 上就是一条 <code>payload</code> 列：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/admin/service/internal/data/ent/schema/bi_dashboard.go</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;payload&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;仪表盘 JSON（设计器 schema：数据集 + 图表布局 + 主题；服务端不解析只透传）&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">SchemaType</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span></span>
<span class="line">        dialect<span class="token punctuation">.</span>MySQL<span class="token punctuation">:</span>    <span class="token string">&quot;json&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        dialect<span class="token punctuation">.</span>Postgres<span class="token punctuation">:</span> <span class="token string">&quot;jsonb&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>「不解析」是刻意的：schema 的版本演进发生在库内（<code>schemaVersion</code> + 迁移器），后端只当字符串存取。这样前端升级图型字段、增加联动声明、调整主题结构，都不需要同步改后端或做数据库迁移；代价是<strong>服务端失去对内容的结构约束</strong>，所有校验必须在库与宿主保存钩子里完成。</p><p><code>kind</code> 把同一套内核复用到三种产物：<code>DASHBOARD</code>（管理页内嵌）、<code>SCREEN</code>（投屏大屏）、<code>TEMPLATE</code>（可复用模板）。三者共享 schema 与渲染器，只在宿主侧决定入口和版式语义——分叉的是产品形态，不是内核。</p><p><code>chart_count</code> / <code>theme_key</code> 是给列表页的读优化列：列表不解析 JSON 就能显示「几张图、什么主题」。代价是写路径要维护一致性，三端保存时都从 schema 现算：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// 三端保存钩子的共同口径</span></span>
<span class="line">chartCount<span class="token operator">:</span> schema<span class="token punctuation">.</span>charts<span class="token operator">?.</span>length <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">themeKey<span class="token operator">:</span> schema<span class="token punctuation">.</span>theme<span class="token operator">?.</span>key <span class="token operator">??</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只要有一个客户端漏传，冗余列就会漂移。它们不是数据库触发器算出来的，而是<strong>宿主保存契约的一部分</strong>——这一点在接入文档里必须写死，否则列表页会逐渐显示过期元数据。</p><h2 id="二、schema-可序列化是硬约束-布局数学只写一份" tabindex="-1"><a class="header-anchor" href="#二、schema-可序列化是硬约束-布局数学只写一份"><span>二、schema：可序列化是硬约束，布局数学只写一份</span></a></h2><p>Schema 的核心结构很小：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/schema/types.ts（节选）</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">interface</span> <span class="token class-name">BiDashboardSchema</span> <span class="token punctuation">{</span></span>
<span class="line">  schemaVersion<span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">  name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">  grid<span class="token operator">?</span><span class="token operator">:</span> Partial<span class="token operator">&lt;</span>BiGridConfig<span class="token operator">&gt;</span><span class="token punctuation">;</span>   <span class="token comment">// 12 列 × 80px 行高 × 8px gap</span></span>
<span class="line">  datasets<span class="token operator">:</span> BiDatasetSchema<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  charts<span class="token operator">:</span> BiChartSchema<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  linkage<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> enabled<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">boolean</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  theme<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> key<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>       <span class="token comment">// 空 = 跟随宿主亮暗</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>charts</code> 里每个图表的坐标、图型、编码、聚合、排序、过滤器、下钻路径全是普通 JSON 字段：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">interface</span> <span class="token class-name">BiChartSchema</span> <span class="token punctuation">{</span></span>
<span class="line">  id<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">  title<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">  datasetId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">  engine<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>               <span class="token comment">// 默认 &quot;echarts&quot;</span></span>
<span class="line">  type<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>                  <span class="token comment">// bar/line/pie/... + 适配器注册的扩展图型</span></span>
<span class="line">  x<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> y<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> w<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> h<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line">  encoding<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    dimension<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>          <span class="token comment">// 类目轴 / 饼名</span></span>
<span class="line">    measure<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>            <span class="token comment">// 单度量</span></span>
<span class="line">    measures<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>         <span class="token comment">// 宽表多度量（优先级最高）</span></span>
<span class="line">    series<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>             <span class="token comment">// 长表系列拆分</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  aggregation<span class="token operator">?</span><span class="token operator">:</span> <span class="token string">&quot;sum&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;avg&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;count&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;max&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;min&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;none&quot;</span><span class="token punctuation">;</span></span>
<span class="line">  sort<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> by<span class="token operator">:</span> <span class="token string">&quot;dimension&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;measure&quot;</span><span class="token punctuation">;</span> order<span class="token operator">:</span> <span class="token string">&quot;asc&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;desc&quot;</span><span class="token punctuation">;</span> topN<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  filters<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">Array</span><span class="token operator">&lt;</span><span class="token punctuation">{</span> field<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> op<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> value<span class="token operator">:</span> <span class="token builtin">unknown</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line">  style<span class="token operator">?</span><span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line">  drill<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> path<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  options<span class="token operator">?</span><span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>  <span class="token comment">// 引擎原生透传覆盖</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>可序列化是硬约束</strong>：schema 里不允许出现函数。图表点击、取数、跳转这些运行时行为全部走注入的回调，而不是塞进 JSON。这条约束同时买到四件事——可落库、可 diff、可迁移、可导出成模板文件。任何「为了方便把 formatter 函数写进 schema」的捷径，都会在第一次跨端保存或导入导出时反噬。</p><p><code>schemaVersion</code> 是迁移链的锚点。<code>migrateSchema</code> 逐级升版，未知版本直接抛错（fail-fast，不吞）；v1→v2 只是补版本号，因为 v2 新增字段全部可选。<code>normalizeSchema</code> 在入口补默认值（grid、图表宽高、encoding），这带来一个后面会反复出现的副作用：<strong>规范化后的 JSON 与服务端原文永远不会字符串相等</strong>。</p><p>布局数学只写一份，设计器画布和渲染器共用：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/schema/layout.ts（节选）</span></span>
<span class="line"><span class="token keyword">const</span> grid <span class="token operator">=</span> <span class="token function">defaultGrid</span><span class="token punctuation">(</span>gridInput<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> placed <span class="token operator">=</span> <span class="token function">flowPlace</span><span class="token punctuation">(</span>charts<span class="token punctuation">,</span> grid<span class="token punctuation">.</span>columns<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> colWidth <span class="token operator">=</span> containerWidth <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">?</span> containerWidth <span class="token operator">/</span> grid<span class="token punctuation">.</span>columns <span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> half <span class="token operator">=</span> grid<span class="token punctuation">.</span>gap <span class="token operator">/</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> items <span class="token operator">=</span> placed<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>chart<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> x <span class="token operator">=</span> chart<span class="token punctuation">.</span>x <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> y <span class="token operator">=</span> chart<span class="token punctuation">.</span>y <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> w <span class="token operator">=</span> chart<span class="token punctuation">.</span>w <span class="token operator">??</span> <span class="token constant">CHART_DEFAULT_SIZE</span><span class="token punctuation">.</span>w<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> h <span class="token operator">=</span> chart<span class="token punctuation">.</span>h <span class="token operator">??</span> <span class="token constant">CHART_DEFAULT_SIZE</span><span class="token punctuation">.</span>h<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    chart<span class="token punctuation">,</span> x<span class="token punctuation">,</span> y<span class="token punctuation">,</span> w<span class="token punctuation">,</span> h<span class="token punctuation">,</span></span>
<span class="line">    left<span class="token operator">:</span> x <span class="token operator">*</span> colWidth <span class="token operator">+</span> half<span class="token punctuation">,</span></span>
<span class="line">    top<span class="token operator">:</span> y <span class="token operator">*</span> grid<span class="token punctuation">.</span>rowHeight <span class="token operator">+</span> half<span class="token punctuation">,</span></span>
<span class="line">    width<span class="token operator">:</span> w <span class="token operator">*</span> colWidth <span class="token operator">-</span> grid<span class="token punctuation">.</span>gap<span class="token punctuation">,</span></span>
<span class="line">    height<span class="token operator">:</span> h <span class="token operator">*</span> grid<span class="token punctuation">.</span>rowHeight <span class="token operator">-</span> grid<span class="token punctuation">.</span>gap<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>flowPlace</code> 负责流式放置：已经带 <code>x/y</code> 的图表保留原坐标，缺失的逐行扫描第一块放得下的空位。设计器拖拽时写回的是栅格坐标，渲染器读到的也是同一套 <code>layoutCharts</code>——<strong>「设计器里拖出来的」和「渲染器里看到的」是同一份数学</strong>，不会出现设计态与运行态各算一套像素的问题。</p><p>没有引入 GridStack 之类现成栅格库，原因也在这里：它们通常直接改 DOM，与 Vue/React 的 vdom 更新冲突；而 12 列绝对定位 + 指针事件把手的组合足够覆盖仪表盘场景，且没有额外依赖。</p><p><img src="https://tx7do.github.io/assets/images/gowind-admin/bi-render-overview.png" alt="渲染器输出：同一份 schema 驱动多种图型与引擎（ECharts 柱/线/环/雷达/漏斗/热力/桑基，S2 透视表，G6 关系图）"></p><h2 id="三、数据链路-resolver-是宿主的插座-transform-是内核的管线" tabindex="-1"><a class="header-anchor" href="#三、数据链路-resolver-是宿主的插座-transform-是内核的管线"><span>三、数据链路：resolver 是宿主的插座，transform 是内核的管线</span></a></h2><p>数据集分两类：<code>static</code> 内嵌行，<code>api</code> 声明式占位。真实取数不在渲染器里，而在宿主注入的 resolver 表里：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/dataset/index.ts</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">type</span> <span class="token class-name">BiDatasetResolver</span> <span class="token operator">=</span> <span class="token punctuation">(</span></span>
<span class="line">  dataset<span class="token operator">:</span> BiDatasetSchema<span class="token punctuation">,</span></span>
<span class="line">  params<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span> <span class="token operator">|</span> <span class="token keyword">undefined</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span>BiRow<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对应的解析逻辑很短，但语义很关键：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/dataset/index.ts（节选）</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>dataset<span class="token punctuation">.</span>type <span class="token operator">===</span> <span class="token string">&quot;static&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> rows<span class="token operator">:</span> dataset<span class="token punctuation">.</span>rows <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> loading<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span> error<span class="token operator">:</span> <span class="token keyword">null</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>resolver<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    rows<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    loading<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">    error<span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">[bi] dataset &quot;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>dataset<span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">&quot; (</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>dataset<span class="token punctuation">.</span>id<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">) is type &quot;api&quot; but no resolver was provided</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> rows <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">resolver</span><span class="token punctuation">(</span>dataset<span class="token punctuation">,</span> dataset<span class="token punctuation">.</span>api<span class="token operator">?.</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> rows<span class="token operator">:</span> <span class="token builtin">Array</span><span class="token punctuation">.</span><span class="token function">isArray</span><span class="token punctuation">(</span>rows<span class="token punctuation">)</span> <span class="token operator">?</span> rows <span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> loading<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span> error<span class="token operator">:</span> <span class="token keyword">null</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 原始错误必须留在控制台：用户可见文案不携带原因（不吞错铁律）</span></span>
<span class="line">  <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">[bi] dataset &quot;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>dataset<span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">&quot; resolver failed</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span> err<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> rows<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> loading<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span> error<span class="token operator">:</span> err <span class="token keyword">instanceof</span> <span class="token class-name">Error</span> <span class="token operator">?</span> err<span class="token punctuation">.</span>message <span class="token operator">:</span> <span class="token function">String</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个设计取向值得记下来：</p><ol><li><strong>没接 resolver 是显式错误，不是静默空图</strong>。api 数据集没有注入取数函数时，卡片进入 error 状态并给出 dataset 名；否则用户只会看到一张空图表，排查方向会从「数据没接」歪到「图表配置错了」。</li><li><strong>错误不静默</strong>。原始错误进控制台，卡片上出现 error 角标（完整原因挂在 tooltip），不会退化成一张看起来正常的空图。</li></ol><p>宿主侧只需要把函数表挂到 env 上：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// Vue</span></span>
<span class="line"><span class="token function">provideBiEnv</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  resolvers<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function-variable function">ds_orders</span><span class="token operator">:</span> <span class="token punctuation">(</span>dataset<span class="token punctuation">,</span> params<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> api<span class="token punctuation">.</span><span class="token function">listOrders</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// React</span></span>
<span class="line"><span class="token operator">&lt;</span>BiProvider env<span class="token operator">=</span><span class="token punctuation">{</span><span class="token punctuation">{</span> resolvers <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token operator">&gt;</span></span>
<span class="line">  <span class="token operator">&lt;</span>BiDashboard schema<span class="token operator">=</span><span class="token punctuation">{</span>schema<span class="token punctuation">}</span> <span class="token operator">/</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">/</span>BiProvider<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>渲染器不持有任何 HTTP 客户端。换 REST、gRPC、另一个服务的聚合接口，改的都是宿主注入的这一层，图表组件零改动。这也是 schema 能保持纯 JSON 的前提：<strong>数据来源是运行时依赖，不是 schema 的一部分</strong>。</p><p>拿到行之后，内核跑一条固定管线：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/dataset/transform.ts</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">transformRows</span><span class="token punctuation">(</span>chart<span class="token operator">:</span> BiChartSchema<span class="token punctuation">,</span> inputRows<span class="token operator">:</span> BiRow<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">:</span> BiRow<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> rows <span class="token operator">=</span> <span class="token function">applyFilters</span><span class="token punctuation">(</span>inputRows<span class="token punctuation">,</span> chart<span class="token punctuation">.</span>filters<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">shouldAggregate</span><span class="token punctuation">(</span>chart<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    rows <span class="token operator">=</span> <span class="token function">aggregateRows</span><span class="token punctuation">(</span>rows<span class="token punctuation">,</span> chart<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  rows <span class="token operator">=</span> <span class="token function">sortRows</span><span class="token punctuation">(</span>rows<span class="token punctuation">,</span> chart<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> rows<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>顺序是<strong>过滤 → 聚合 → 排序/TopN</strong>，设计器画布与渲染器共用。几个容易踩的细节：</p><ul><li><code>aggregation</code> 缺省是 <code>sum</code>，设成 <code>&quot;none&quot;</code> 才关闭聚合；</li><li><code>sankey</code> / <code>graph</code> / <code>heatmap</code> 这类边列表、矩阵型图表天然按行消费，<code>NON_AGG_TYPES</code> 会跳过聚合；</li><li>宽表多度量（<code>measures</code>）与长表系列拆分（<code>series</code>）互斥，<code>measures</code> 优先；<code>pivot</code> 的列维度会在聚合时保留，供 S2 交叉表使用；</li><li>数值统一走 <code>toNumber</code>，非有限数归 0——图表轴不允许 <code>NaN</code>/<code>undefined</code>；</li><li>图表级 <code>filters</code> 与跨图联动共用 <code>applyFilters</code>，联动只是把「点击值 = 某字段」这条过滤条件追加到数据集行上。</li></ul><h2 id="四、渲染链路-三个方法接一个引擎-主题在编译期落进-option" tabindex="-1"><a class="header-anchor" href="#四、渲染链路-三个方法接一个引擎-主题在编译期落进-option"><span>四、渲染链路：三个方法接一个引擎，主题在编译期落进 option</span></a></h2><p>图表引擎的抽象只有三个方法：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/engine/types.ts</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">interface</span> <span class="token class-name">ChartEngine</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/** 挂载容器并渲染首帧（option 由 compile 产出） */</span></span>
<span class="line">  <span class="token function">mount</span><span class="token punctuation">(</span>el<span class="token operator">:</span> HTMLElement<span class="token punctuation">,</span> option<span class="token operator">:</span> <span class="token builtin">unknown</span><span class="token punctuation">)</span><span class="token operator">:</span> ChartHandle<span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">/** schema + 行数据 + 主题 → 引擎原生 option */</span></span>
<span class="line">  <span class="token function">compile</span><span class="token punctuation">(</span>chart<span class="token operator">:</span> BiChartSchema<span class="token punctuation">,</span> rows<span class="token operator">:</span> BiRow<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> theme<span class="token operator">:</span> BiResolvedTheme<span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">unknown</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">/** 订阅归一化点击事件 */</span></span>
<span class="line">  <span class="token function">bindEvents</span><span class="token punctuation">(</span>handle<span class="token operator">:</span> ChartHandle<span class="token punctuation">,</span> <span class="token function-variable function">cb</span><span class="token operator">:</span> <span class="token punctuation">(</span>e<span class="token operator">:</span> BiChartEvent<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">interface</span> <span class="token class-name">ChartHandle</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">update</span><span class="token punctuation">(</span>option<span class="token operator">:</span> <span class="token builtin">unknown</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">resize</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">dispose</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line">  getDataURL<span class="token operator">?</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token operator">|</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span>   <span class="token comment">// 导出 PNG 用，引擎不支持可不实现</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>主题在<strong>编译期</strong>写进 option，引擎层不负责主题切换——换主题就是重新 <code>compile</code> + <code>update</code>。这样 ECharts、S2、G6 各适配器不需要各自实现一套主题监听，亮暗切换只有一条路径。</p><p>图型通过注册表映射到引擎：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/engine/chart-types.ts（节选）</span></span>
<span class="line"><span class="token keyword">const</span> typeToEngine <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">string</span><span class="token operator">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> t <span class="token keyword">of</span> <span class="token constant">BUILTIN_CHART_TYPES</span><span class="token punctuation">)</span> typeToEngine<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>t<span class="token punctuation">,</span> <span class="token string">&quot;echarts&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">registerChartType</span><span class="token punctuation">(</span>type<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> engine<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token punctuation">{</span></span>
<span class="line">  typeToEngine<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>type<span class="token punctuation">,</span> engine<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>内置 13 种 ECharts 图型（柱/线/面/饼/环/散点/雷达/仪表/漏斗/矩形树/旭日/桑基/热力）。可选适配器按需安装：</p><ul><li><code>@go-wind/bi-engine-s2</code> 注册 <code>pivot</code>，走 AntV S2 交叉表；</li><li><code>@go-wind/bi-engine-g6</code> 注册 <code>graph</code>，走 AntV G6 关系图。</li></ul><p>未注册的引擎会直接抛错并指路安装哪个适配器包，而不是静默回落到 ECharts。图型注册同时驱动设计器的图型网格——装了 G6，选图面板里才会出现「关系图」。</p><p>G6 适配器把行当作边列表消费，字段映射固定为「起点/终点/权重」：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-engine-g6/src/index.ts（节选）</span></span>
<span class="line"><span class="token keyword">const</span> sourceField <span class="token operator">=</span> enc<span class="token punctuation">.</span>dimension <span class="token operator">??</span> <span class="token string">&quot;source&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> targetField <span class="token operator">=</span> enc<span class="token punctuation">.</span>series <span class="token operator">??</span> <span class="token string">&quot;target&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> weightField <span class="token operator">=</span> enc<span class="token punctuation">.</span>measure<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>measure</code> 映射到连线宽度（钳制在 2–10），布局用 force，事件通过 <code>bindEvents</code> 归一化成统一的 <code>BiChartEvent</code>。跨引擎联动因此不需要关心底层是 canvas 还是 SVG。</p><p>主题分两层：</p><ul><li><strong>图表 token</strong>：亮/暗两套 text/subText/axisLine/splitLine + 10 色盘，<code>resolveTheme(mode)</code> 产出；</li><li><strong>舞台预设</strong>：<code>theme.key</code> 命中预设时，把图表色彩模式、画布底色、卡片 chrome 一起钉死。</li></ul><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/theme/presets.ts（节选）</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">resolveDashboardTheme</span><span class="token punctuation">(</span>key<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token operator">|</span> <span class="token keyword">undefined</span><span class="token punctuation">,</span> autoIsDark<span class="token operator">:</span> <span class="token builtin">boolean</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> preset <span class="token operator">=</span> <span class="token function">getDashboardThemePreset</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>preset<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> theme<span class="token operator">:</span> <span class="token function">resolveTheme</span><span class="token punctuation">(</span>autoIsDark <span class="token operator">?</span> <span class="token string">&quot;dark&quot;</span> <span class="token operator">:</span> <span class="token string">&quot;light&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> preset<span class="token operator">:</span> <span class="token keyword">null</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">const</span> base <span class="token operator">=</span> <span class="token function">resolveTheme</span><span class="token punctuation">(</span>preset<span class="token punctuation">.</span>mode<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    theme<span class="token operator">:</span> preset<span class="token punctuation">.</span>palette <span class="token operator">?</span> <span class="token punctuation">{</span> <span class="token operator">...</span>base<span class="token punctuation">,</span> palette<span class="token operator">:</span> preset<span class="token punctuation">.</span>palette <span class="token punctuation">}</span> <span class="token operator">:</span> base<span class="token punctuation">,</span></span>
<span class="line">    preset<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>key</code> 为空时跟随宿主：<code>html.dark</code> 优先，其次系统 <code>prefers-color-scheme</code>；<code>watchDark</code> 维护一份模块级共享的 <code>MutationObserver</code> + <code>matchMedia</code> 监听，Vue 和 React 两端共用同一个观察者。卡片 chrome 不写死颜色，而是经 <code>--bi-card-bg</code> / <code>--bi-card-border</code> / <code>--bi-canvas-bg</code> 变量下发，宿主可以整体接管；图表 <code>backgroundColor</code> 恒为 <code>transparent</code>，让宿主背景透出。</p><p>渲染器还负责三类交互：</p><ul><li><strong>跨图联动</strong>：点击带维度值的图表，按 <code>datasetId</code> 槽位过滤消费同一数据集的兄弟图表；点同值取消；</li><li><strong>下钻</strong>：<code>drill.path</code> 声明维度层级，点击后把当前层维度替换为下一层，祖先值作为隐式 <code>eq</code> 过滤器携带；</li><li><strong>卡片工具</strong>：单图导出 PNG（把引擎 canvas 复制到白底画布）、全屏（元素级 <code>requestFullscreen</code>）。</li></ul><p>下钻的生效逻辑集中在 <code>effectiveChart</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-vue/src/BiDashboard.vue（节选）</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">effectiveChart</span><span class="token punctuation">(</span>chart<span class="token operator">:</span> BiChartSchema<span class="token punctuation">)</span><span class="token operator">:</span> BiChartSchema <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> st <span class="token operator">=</span> drillStates<span class="token punctuation">[</span>chart<span class="token punctuation">.</span>id<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>st <span class="token operator">||</span> <span class="token operator">!</span>chart<span class="token punctuation">.</span>drill<span class="token operator">?.</span>path<span class="token operator">?.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> chart<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> path <span class="token operator">=</span> chart<span class="token punctuation">.</span>drill<span class="token punctuation">.</span>path<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> dim <span class="token operator">=</span> path<span class="token punctuation">[</span>Math<span class="token punctuation">.</span><span class="token function">min</span><span class="token punctuation">(</span>st<span class="token punctuation">.</span>level<span class="token punctuation">,</span> path<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> extraFilters <span class="token operator">=</span> st<span class="token punctuation">.</span>parents<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    field<span class="token operator">:</span> p<span class="token punctuation">.</span>field<span class="token punctuation">,</span> op<span class="token operator">:</span> <span class="token string">&quot;eq&quot;</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">,</span> value<span class="token operator">:</span> p<span class="token punctuation">.</span>value<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token operator">...</span>chart<span class="token punctuation">,</span></span>
<span class="line">    encoding<span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token operator">...</span>chart<span class="token punctuation">.</span>encoding<span class="token punctuation">,</span> dimension<span class="token operator">:</span> dim <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    filters<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">(</span>chart<span class="token punctuation">.</span>filters <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">...</span>extraFilters<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>大屏场景的缩放由 <code>view</code> 控制：<code>designWidth</code> 是设计稿宽度，<code>fit</code> 有 <code>width</code>（只按宽缩放，高度随内容）、<code>contain</code>（双向取小并居中，不滚动）、<code>none</code>（1:1）三种语义。渲染器用 <code>transform: scale()</code> 缩放绝对定位网格，布局仍按设计稿宽度计算——这样投屏分辨率变化时，图表不会各自重排。</p><h2 id="五、设计器-框架无关的状态机-外面套两层-ui" tabindex="-1"><a class="header-anchor" href="#五、设计器-框架无关的状态机-外面套两层-ui"><span>五、设计器：框架无关的状态机，外面套两层 UI</span></a></h2><p>设计器的核心不是画布，而是一个纯 TS 状态机 <code>BiDesignerApi</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// packages/bi-core/src/designer/designer-api.ts（节选）</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token function">commit</span><span class="token punctuation">(</span><span class="token function-variable function">mutator</span><span class="token operator">:</span> <span class="token punctuation">(</span>draft<span class="token operator">:</span> BiDashboardSchema<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">this</span><span class="token punctuation">.</span>undoStack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>store<span class="token punctuation">.</span><span class="token function">getState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>undoStack<span class="token punctuation">.</span>length <span class="token operator">&gt;</span> <span class="token constant">UNDO_LIMIT</span><span class="token punctuation">)</span> <span class="token keyword">this</span><span class="token punctuation">.</span>undoStack<span class="token punctuation">.</span><span class="token function">shift</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">this</span><span class="token punctuation">.</span>redoStack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> draft <span class="token operator">=</span> <span class="token function">deepClone</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>store<span class="token punctuation">.</span><span class="token function">getState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">mutator</span><span class="token punctuation">(</span>draft<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">this</span><span class="token punctuation">.</span>store<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>draft<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>所有 mutation 走 <code>commit()</code>：先压快照到撤销栈（上限 50），清空重做栈，深拷贝出下一状态，再整体替换。快照语义让撤销/重做不需要反向操作，也不会被嵌套引用污染。</li><li>选中状态 <code>select()</code> 不进撤销栈——点选图表不是内容变更，不应该让用户按一次 Ctrl+Z 只取消选中。</li><li>新增图表先 <code>findFreeSpot</code> 找空位；移动/缩放后跑 <code>resolveCollisions</code>：与锚点重叠的图表依次压到锚点下方，被压者成为新的锚点继续级联下推，100 轮上限防循环。</li><li>缩放有下限 <code>3×2</code> 栅格单位；<code>compact()</code> 按 y/x 排序后重新流式压紧，消掉拖拽留下的空洞。</li><li>剪贴板是组件内单卡槽，<code>copyChart</code> 存深拷贝，<code>pasteChart</code> 换新 id + 自动找空位。</li><li>导入走 <code>migrateSchema</code>（fail-fast），成功后清空撤销栈；导出就是 <code>JSON.stringify(schema)</code>，可直接落库或存文件。</li></ul><p>外面套的第一层 UI 是 Vue 设计器：左栏数据集、中间画布、右栏属性面板（数据/样式/布局三个 tab）。图型选择是一个网格，拖拽和缩放用指针事件按栅格吸附，键盘支持 Ctrl+Z/Y/C/V/D、Delete、Esc。工具栏还有模板菜单、跨图联动开关、主题下拉、导入/导出、预览。模板文件走 <code>.gwbi.json</code> 契约：<code>$gwbi: &quot;template&quot;</code> 魔术标识 + 文件格式版本 + meta + schema，服务端模板 CRUD 属于宿主职责，库只保证文件可解析、schema 走迁移器。</p><p><img src="https://tx7do.github.io/assets/images/gowind-admin/bi-designer-canvas.png" alt="设计器：数据集、画布、属性面板三栏；右侧为数据 tab（图型、编码、下钻路径、聚合、排序、过滤器）"></p><p><img src="https://tx7do.github.io/assets/images/gowind-admin/bi-designer-style.png" alt="属性面板的样式 tab：图例、数值标签、堆叠、数据缩放、色盘、数字格式"></p><p>第二层是 React 桥接壳。设计器只做 Vue 一等公民，React 端用 <code>createApp</code> 把 Vue 设计器挂进 React 容器：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code><span class="line"><span class="token comment">// packages/bi-react/src/BiDesignerBridge.tsx（节选）</span></span>
<span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> initial <span class="token operator">=</span> mountPropsRef<span class="token punctuation">.</span>current<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> DesignerRoot <span class="token operator">=</span> <span class="token function">defineComponent</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">setup</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span>initial<span class="token punctuation">.</span>env<span class="token punctuation">)</span> <span class="token function">provideBiEnv</span><span class="token punctuation">(</span>initial<span class="token punctuation">.</span>env<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">h</span><span class="token punctuation">(</span>BiDesigner <span class="token keyword">as</span> Component<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">        initialSchema<span class="token operator">:</span> initial<span class="token punctuation">.</span>initialSchema<span class="token punctuation">,</span></span>
<span class="line">        demo<span class="token operator">:</span> initial<span class="token punctuation">.</span>demo <span class="token operator">??</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token function-variable function">onChange</span><span class="token operator">:</span> <span class="token punctuation">(</span>schema<span class="token operator">:</span> BiDashboardSchema<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> onChangeRef<span class="token punctuation">.</span>current<span class="token operator">?.</span><span class="token punctuation">(</span>schema<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> app <span class="token operator">=</span> <span class="token function">createApp</span><span class="token punctuation">(</span>DesignerRoot<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  app<span class="token punctuation">.</span><span class="token function">mount</span><span class="token punctuation">(</span>host<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> app<span class="token punctuation">.</span><span class="token function">unmount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> host<span class="token punctuation">.</span>innerHTML <span class="token operator">=</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 仅挂载一次：运行期改 props 不重建</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个细节决定了这层壳能不能用：</p><ol><li><strong><code>onChange</code> 经 ref 转发</strong>。React 侧回调函数身份每次渲染都可能变化，直接作为 prop 传进去会触发 Vue 应用重建；ref 让回调始终指向最新的 React 函数，同时保持挂载稳定。</li><li><strong><code>initialSchema</code> 是挂载时快照</strong>。运行期改这个 prop 不会回灌画布——画布内部的撤销栈、选区不应该被外部 schema 更新打断。宿主想切换编辑目标，必须换 <code>key</code> 强制重挂载。</li><li><strong>样式是两份</strong>。React 容器样式来自 <code>@go-wind/bi-react/style.css</code>，画布网格/卡片样式在 <code>@go-wind/bi-vue/style.css</code>，两份都要引。这不是冗余，是桥接壳的物理事实。</li></ol><p>卡片视觉全部在 <code>bi-react/styles.css</code> 的 <code>.bi-dashboard__card</code> 等规则里（含 <code>html.dark</code> 分支），<strong>不允许 inline 写视觉值</strong>——inline 优先级会压过 CSS 暗色分支，auto 主题切暗时卡片会恒浅。宿主接管时覆盖 <code>--bi-card-*</code> 变量链即可，不用改组件。</p><h2 id="六、持久化-黑盒-payload、cas-与可逆快照" tabindex="-1"><a class="header-anchor" href="#六、持久化-黑盒-payload、cas-与可逆快照"><span>六、持久化：黑盒 payload、CAS 与可逆快照</span></a></h2><p>写入语义由三件套构成：主表 <code>version</code> 乐观锁、保存前快照、快照表 <code>(dashboard_id, version)</code> 唯一索引。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/admin/service/internal/data/ent/schema/bi_dashboard.go（节选）</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">Uint32</span><span class="token punctuation">(</span><span class="token string">&quot;version&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;版本号（乐观锁：更新需回传读到的版本，成功后 +1）&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Default</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Nillable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 编码租户内唯一：业务按 (tenant, code) 取仪表盘，跨租户重码不冲突</span></span>
<span class="line">index<span class="token punctuation">.</span><span class="token function">Fields</span><span class="token punctuation">(</span><span class="token string">&quot;code&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;tenant_id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">StorageKey</span><span class="token punctuation">(</span><span class="token string">&quot;uidx_bi_dashboards_code_tenant&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>更新分两条路：带 <code>version</code> 走 CAS，不带则普通更新。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/admin/service/internal/data/bi_dashboard_repo.go（节选）</span></span>
<span class="line"><span class="token keyword">if</span> req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span>Version <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> r<span class="token punctuation">.</span><span class="token function">updateWithVersionCAS</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">return</span> r<span class="token punctuation">.</span><span class="token function">updatePlain</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// updateWithVersionCAS</span></span>
<span class="line">builder <span class="token operator">:=</span> r<span class="token punctuation">.</span>entClient<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>BiDashboard<span class="token punctuation">.</span><span class="token function">Update</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Where</span><span class="token punctuation">(</span></span>
<span class="line">        bidashboard<span class="token punctuation">.</span><span class="token function">IDEQ</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        bidashboard<span class="token punctuation">.</span><span class="token function">VersionEQ</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span><span class="token function">GetVersion</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">SetNillablePayload</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span>Payload<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token comment">// …其余 SetNillable</span></span>
<span class="line">    <span class="token function">AddVersion</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">affected<span class="token punctuation">,</span> err <span class="token operator">:=</span> builder<span class="token punctuation">.</span><span class="token function">Save</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> affected <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">    exist<span class="token punctuation">,</span> existErr <span class="token operator">:=</span> r<span class="token punctuation">.</span><span class="token function">IsExist</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> existErr <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> existErr <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>exist <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> adminV1<span class="token punctuation">.</span><span class="token function">ErrorNotFound</span><span class="token punctuation">(</span><span class="token string">&quot;bi dashboard not found&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> adminV1<span class="token punctuation">.</span><span class="token function">ErrorConflict</span><span class="token punctuation">(</span><span class="token string">&quot;bi dashboard has been modified by another session, reload and retry&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个容易忽略的取舍：</p><ul><li><strong>0 命中要区分「行已删」与「版本过期」</strong>。只返回 409 会让用户以为被并发修改，实际是记录没了；先 <code>IsExist</code> 再分别给 404 / 409，前端才能给出正确提示。</li><li><strong>普通更新也 <code>AddVersion(1)</code></strong>。列表页改启用状态不回传 version，但它同样推进版本号——这样持有旧版本的设计器下一次保存会撞 409，不会静默覆盖。</li><li><strong>CAS 是整份覆盖的闸门，不是字段级合并</strong>。设计器保存的是整份 payload，冲突后前端刷新版本继续编辑，下一次保存会以本地画布覆盖对方版本。409 的语义是「阻止这次静默覆盖」，不是自动合并；这是整份覆盖模型的必然取舍。</li></ul><p>快照在 service 层做：更新前先读旧行，更新成功后落快照。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/admin/service/internal/service/bi_dashboard_service.go（节选）</span></span>
<span class="line">current<span class="token punctuation">,</span> getErr <span class="token operator">:=</span> s<span class="token punctuation">.</span>biDashboardRepo<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>biV1<span class="token punctuation">.</span>GetBiDashboardRequest<span class="token punctuation">{</span></span>
<span class="line">    QueryBy<span class="token punctuation">:</span> <span class="token operator">&amp;</span>biV1<span class="token punctuation">.</span>GetBiDashboardRequest_Id<span class="token punctuation">{</span>Id<span class="token punctuation">:</span> req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> getErr <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    s<span class="token punctuation">.</span>log<span class="token punctuation">.</span><span class="token function">Warnf</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;snapshot before update: load dashboard %d failed: %s&quot;</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> getErr<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">=</span> s<span class="token punctuation">.</span>biDashboardRepo<span class="token punctuation">.</span><span class="token function">Update</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> current <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> s<span class="token punctuation">.</span>revisionRepo <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    snapshot <span class="token operator">:=</span> <span class="token operator">&amp;</span>biV1<span class="token punctuation">.</span>BiDashboardRevision<span class="token punctuation">{</span></span>
<span class="line">        DashboardId<span class="token punctuation">:</span> req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Version<span class="token punctuation">:</span>     current<span class="token punctuation">.</span><span class="token function">GetVersion</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Name<span class="token punctuation">:</span>        current<span class="token punctuation">.</span>Name<span class="token punctuation">,</span></span>
<span class="line">        Payload<span class="token punctuation">:</span>     current<span class="token punctuation">.</span>Payload<span class="token punctuation">,</span></span>
<span class="line">        Source<span class="token punctuation">:</span>      trans<span class="token punctuation">.</span><span class="token function">Ptr</span><span class="token punctuation">(</span><span class="token string">&quot;SAVE&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        CreatedBy<span class="token punctuation">:</span>   trans<span class="token punctuation">.</span><span class="token function">Ptr</span><span class="token punctuation">(</span>operator<span class="token punctuation">.</span>UserId<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">if</span> serr <span class="token operator">:=</span> s<span class="token punctuation">.</span>revisionRepo<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> snapshot<span class="token punctuation">)</span><span class="token punctuation">;</span> serr <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        s<span class="token punctuation">.</span>log<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;snapshot before update dashboard %d failed: %s&quot;</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span><span class="token function">GetId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> serr<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意快照存的是<strong>保存前</strong>的旧行，不是保存后的新行。所以 <code>revisions</code> 里不会立刻出现当前版本；它是一串「可回退点」，而不是「每次结果的审计流水」。恢复语义也建立在这个模型上：</p><ul><li>取目标快照 → 取当前主表行；</li><li>先把当前行以 <code>source=RESTORE</code> 留一份快照；</li><li>再把目标快照的 <code>name/payload</code> 通过 fieldmask 写回主表，版本号 +1。</li></ul><p>恢复动作本身可逆——误恢复后还能再恢复回来。恢复写回<strong>不走 CAS</strong>：它是操作员明确选择「以这份快照为准」的人为决定，按快照覆盖 <code>name/payload</code>；但版本号照样 +1，其他编辑器下一次保存仍会撞 409。</p><p>快照表的约束全部围绕这套语义：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/admin/service/internal/data/ent/schema/bi_dashboard_revision.go（节选）</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">Int64</span><span class="token punctuation">(</span><span class="token string">&quot;dashboard_id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;所属仪表盘 ID&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">Uint32</span><span class="token punctuation">(</span><span class="token string">&quot;version&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;快照对应的仪表盘版本号（保存前的旧版本）&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;保存前的名称快照（恢复时一并写回）&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;payload&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;保存前的仪表盘 JSON 快照&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">field<span class="token punctuation">.</span><span class="token function">Enum</span><span class="token punctuation">(</span><span class="token string">&quot;source&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">NamedValues</span><span class="token punctuation">(</span><span class="token string">&quot;SAVE&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;SAVE&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;RESTORE&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;RESTORE&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Default</span><span class="token punctuation">(</span><span class="token string">&quot;SAVE&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 一张仪表盘一个版本号只留一份快照（保存/恢复去重）</span></span>
<span class="line">index<span class="token punctuation">.</span><span class="token function">Fields</span><span class="token punctuation">(</span><span class="token string">&quot;dashboard_id&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;version&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">StorageKey</span><span class="token punctuation">(</span><span class="token string">&quot;uidx_bi_revisions_dash_version&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>(dashboard_id, version)</code> 唯一：并发保存同一旧版本时，重复快照会被数据库挡掉，不会产生两条分不清先后的记录；</li><li><code>source</code> 区分常规保存与恢复前留底；</li><li>边配 <code>OnDelete: Cascade</code>，删仪表盘时快照一起清；</li><li>仓储只有 <code>Create/List/Get</code> 三个动作，表级没有更新/删除入口——快照只增不改。</li></ul><p>把这套语义抽出来，是一个可复用的快照判型：</p><ul><li>有并发写入的资源：快照键带 <code>version</code> 并加唯一索引，主表用 CAS 挡住 stale 写；</li><li>纯单人编辑的资源：按 <code>created_at</code> 排序即可，不必引入版本号；</li><li>无论哪种，<strong>恢复前先留底</strong>不能省——否则「恢复」本身就是一次不可逆覆盖。</li></ul><p>前端自动保存要把三条契约同时守住，否则「回显」和「保存」会互相打架：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code><span class="line"><span class="token comment">// frontend/admin/react/src/pages/app/bi-designer/index.tsx（节选）</span></span>
<span class="line"><span class="token keyword">const</span> onSchemaChange <span class="token operator">=</span> <span class="token function">useCallback</span><span class="token punctuation">(</span><span class="token punctuation">(</span>schema<span class="token operator">:</span> BiDashboardSchema<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> payloadStr <span class="token operator">=</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>schema<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>dashboardId<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 首帧 emit = 加载内容的规范化形态，定为基线</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>baselineRef<span class="token punctuation">.</span>current <span class="token operator">===</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      baselineRef<span class="token punctuation">.</span>current <span class="token operator">=</span> payloadStr<span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>payloadStr <span class="token operator">===</span> baselineRef<span class="token punctuation">.</span>current<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">clearTimer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    saveTimer<span class="token punctuation">.</span>current <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span></span>
<span class="line">      <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">saveToServer</span><span class="token punctuation">(</span>schema<span class="token punctuation">,</span> payloadStr<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token constant">SAVE_DEBOUNCE_MS</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 无 id：本地草稿，不进服务端</span></span>
<span class="line">    <span class="token function">clearTimer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    saveTimer<span class="token punctuation">.</span>current <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">      localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token constant">DRAFT_KEY</span><span class="token punctuation">,</span> payloadStr<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token constant">SAVE_DEBOUNCE_MS</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>dashboardId<span class="token punctuation">,</span> saveToServer<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>契约一：首帧 emit 定基线。</strong> <code>normalizeSchema</code> 补默认值后，画布规范化 JSON 与服务端原文永不字符串相等。如果拿原文当基线，加载完成的第一帧就会被判定为「有改动」，自动保存立刻把规范化结果写回，制造一次无意义的版本推进。正确做法是把画布第一次 emit 的串当基线，跳过它；此后与基线相同也跳过，保存成功后更新基线。</p><p><strong>契约二：取数完成前不挂画布。</strong> <code>initialSchema</code> 是挂载时快照，不会回灌。如果画布先以 demo schema 挂载、后端数据后到，画布不会重置成真实行；自动保存反而会把 demo 内容覆盖进库。所以三端都设了 <code>ready</code> 门：先取后端行/本地草稿，再挂 <code>&lt;BiDesigner&gt;</code>；切换 <code>?id=</code> 时靠 <code>key</code> 强制重挂载。</p><p><strong>契约三：409 后刷新版本，不丢本地编辑。</strong> 保存失败且命中冲突时，前端保持当前画布，重新拉一次详情把 <code>versionRef</code> 刷到服务端最新；后续编辑用新版本继续保存。代价是对方那一版会被覆盖——再次说明 CAS 在这里是「防静默覆盖」，不是「自动合并」。</p><h2 id="七、三端接入-同一心智模型-三种宿主形态" tabindex="-1"><a class="header-anchor" href="#七、三端接入-同一心智模型-三种宿主形态"><span>七、三端接入：同一心智模型，三种宿主形态</span></a></h2><p>三端的管理页、设计器页、仪表盘页结构一致，差异集中在表格/抽屉框架和画布容器适配：</p><table><thead><tr><th>端</th><th>列表</th><th>设计器</th><th>关键差异</th></tr></thead><tbody><tr><td>React</td><td>antd ProTable + TanStack Query</td><td>全屏抽屉 + 独立页，<code>BiDesignerReact</code></td><td>桥接壳，两份 <code>style.css</code></td></tr><tr><td>vue-element</td><td>自研 ProPage 配置驱动</td><td>独立页 + <code>ElDialog</code> 抽屉</td><td><code>fit</code> 反推设计宽，<code>overflow:hidden</code> 断反馈环</td></tr><tr><td>vue-vben</td><td><code>useVbenVxeGrid</code></td><td><code>useVbenDrawer</code> + 基础信息表单</td><td>关闭守卫，<code>flex</code> 高度链</td></tr></tbody></table><p><strong>React 端</strong>的独立设计器页负责「加载 → 基线 → 防抖保存 → 409 刷新」全链路，管理页则用全屏抽屉复用同一个桥接壳。版本历史是行内弹窗：版本/名称/来源/时间 + 恢复按钮；恢复成功后同时失效快照列表和仪表盘列表缓存。</p><p><strong>vue-element 端</strong>的仪表盘页做了一个容易被忽略的适配：<code>fit=width</code> 只按容器宽度等比缩放，宽扁容器（横幅式仪表盘）下方会留大片空白。于是宿主按容器宽高比反推设计宽：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// frontend/admin/vue-element/src/pages/app/bi/dashboard/index.vue（节选）</span></span>
<span class="line"><span class="token keyword">const</span> width <span class="token operator">=</span> el<span class="token punctuation">.</span>clientWidth<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> height <span class="token operator">=</span> el<span class="token punctuation">.</span>clientHeight <span class="token operator">-</span> <span class="token number">2</span><span class="token punctuation">;</span>   <span class="token comment">// 留 2px 余量，避免取整误差顶出滚动条</span></span>
<span class="line"><span class="token keyword">const</span> contentHeight <span class="token operator">=</span> <span class="token function">contentHeightOf</span><span class="token punctuation">(</span>schema<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>width <span class="token operator">&lt;=</span> <span class="token number">0</span> <span class="token operator">||</span> height <span class="token operator">&lt;=</span> <span class="token number">0</span> <span class="token operator">||</span> contentHeight <span class="token operator">&lt;=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">designWidth<span class="token punctuation">.</span>value <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">min</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token number">3840</span><span class="token punctuation">,</span></span>
<span class="line">  Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">960</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">round</span><span class="token punctuation">(</span><span class="token punctuation">(</span>contentHeight <span class="token operator">*</span> width<span class="token punctuation">)</span> <span class="token operator">/</span> height<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>内容高度直接复用渲染器的 <code>layoutCharts(..., 1920).height</code>，避免公式重复走样；960–3840 的钳位防极端值；容器再配 <code>overflow:hidden</code>，断开「出滚动条 → 容器变窄 → 重算 → 滚动条消失 → 变宽」的布局反馈环。全屏时还要把页面底色刷成当前主题布局底色，否则 fullscreen 元素会透出浏览器 UA 黑底。</p><p><strong>vue-vben 端</strong>把设计器放进抽屉，上部是基础信息表单，下部是画布。抽屉的关闭守卫靠捕获阶段标记脏数据：</p><div class="language-vue line-numbers-mode" data-highlighter="prismjs" data-ext="vue"><pre><code><span class="line"><span class="token comment">&lt;!-- frontend/admin/vue-vben/src/views/app/bi/manage/bi-designer-drawer.vue（节选） --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span></span>
<span class="line">  <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>min-h-0 flex-1<span class="token punctuation">&quot;</span></span></span>
<span class="line">  <span class="token attr-name">@pointerdown.capture</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>canvasDirty = true<span class="token punctuation">&quot;</span></span></span>
<span class="line">  <span class="token attr-name">@keydown.capture</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>canvasDirty = true<span class="token punctuation">&quot;</span></span></span>
<span class="line"><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token comment">&lt;!-- 不能写 display:block：会压过组件 scoped 的 display:flex，</span>
<span class="line">       内部 __body flex:1 失效 → 画布塌成内容高、无法滚动 --&gt;</span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>BiDesigner</span></span>
<span class="line">    <span class="token attr-name">:key</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>canvasKey<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:demo</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mode === &#39;create&#39;<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:initial-schema</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>initialSchema<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">height</span><span class="token punctuation">:</span> 100%</span><span class="token punctuation">&quot;</span></span></span></span>
<span class="line">    <span class="token attr-name">@change</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>handleSchemaChange<span class="token punctuation">&quot;</span></span></span>
<span class="line">  <span class="token punctuation">/&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>onBeforeClose</code> 里无脏数据直通，有脏数据弹确认；确认放弃才关，保存成功后重置 <code>canvasDirty</code>。这里还有一个 CSS 细节：画布容器不能写 <code>display:block</code>，否则会压过组件 scoped 的 <code>display:flex</code>，内部 <code>__body</code> 的 <code>flex:1</code> 失效，画布塌成内容高、抽屉里无法滚动。第三方画布组件的「撑满父容器」依赖一整条高度链，任何一环改成 block 都会断。</p><p>三端还有几个共同约定：</p><ul><li>BI 路由是<strong>前端路由自带</strong>，不走后端种子菜单；权限码统一（<code>sys:platform_admin</code> / <code>sys:tenant_manager</code>），避免三端各写一套。</li><li>渲染页的 schema 优先级是 <code>?id=</code> 后端行 &gt; localStorage 草稿 &gt; 内置演示；设计器页无 id 时写本地草稿，有 id 时自动保存回服务端。</li><li>管理页的「设计 / 版本历史 / 复制 / 删除」动作里，内置行禁删、可复制派生。副本恒为非内置、版本归 1，名称缺省追加 <code>-copy</code>；编码缺省用 <code>id.NewShortUUID()</code> 生成——时间戳后缀在同一秒内复制两次必撞，纳秒级在 Windows 时钟粒度下也可能连续两次取到同一读数。</li><li>内置种子 <code>builtin.bi.basic</code> 是 <code>TEMPLATE</code>，启动期按 <code>code</code> 缺一补一、不覆盖；内置行落平台租户，租户侧使用走「复制内置模板派生本租户行」。</li></ul><h2 id="八、失败模式-五类可复现的接入事故" tabindex="-1"><a class="header-anchor" href="#八、失败模式-五类可复现的接入事故"><span>八、失败模式：五类可复现的接入事故</span></a></h2><p>接入第三方画布内核时，下面五类问题几乎一定会遇到。它们都不是 API 用错，而是<strong>边界假设错位</strong>。</p><p><strong>一、样式不在，DOM 在。</strong> 组件挂载成功、canvas 也在 DOM 里，但高度为 0，页面看起来是「图表没渲染」。原因是库的布局依赖样式包里的 scoped CSS（绝对定位网格、flex 卡片、图表容器尺寸）；宿主只引了组件 JS，没引 <code>style.css</code>。症状是白渲染而非报错，第一反应容易误判成图表库版本问题。规则：<strong>带样式的组件库，<code>style.css</code> 与组件同生共死</strong>；React 桥接壳要引两份（容器 + 画布）。</p><p><strong>二、<code>exclude</code> 是子树操作，不是单包操作。</strong> 为了让含 <code>?worker</code> 导入的编辑器包走源码链路，vite 配了 <code>optimizeDeps.exclude</code>；但被 exclude 的包，其<strong>传递依赖同样不预构建</strong>。其中裸 CJS 包（<code>lowlight</code> 深引 <code>highlight.js/lib/*</code>、<code>@tiptap/react</code> 从 <code>use-sync-external-store/shim</code> 具名导入）直接进浏览器解析不了具名导出，整页白屏。修法是把这些 CJS 依赖显式纳入 <code>include</code>，让预构建转成 ESM。规则：exclude 一个包之前，先列出它整棵依赖树里的 CJS 节点。</p><p><strong>三、等比缩放会遇到容器反馈环。</strong> <code>fit=width</code> 只按宽度缩放，宽扁容器下方留白；按容器宽高比反推设计宽后，又容易触发「滚动条出现 → 容器变窄 → 重算 → 滚动条消失」的循环。规则：反推公式 + 钳位 + <code>overflow:hidden</code> 三件套一起上，缺一个都会抖。</p><p><strong>四、回显会被自动保存写成「误保存」。</strong> 规范化后的 JSON 与原文不相等，拿原文当基线会在加载首帧触发保存；画布在取数完成前挂载，会把 demo 内容覆盖进库。规则：<strong>先 ready 再挂画布，首帧 emit 定基线，保存成功后再更新基线</strong>。这三条是宿主保存契约，不是可选优化。</p><p><strong>五、默认值本身就是钉死。</strong> schema 不写 <code>theme.key</code> 的语义是「跟随宿主亮暗」；但如果演示 schema 或内置种子写死了一个具体预设，宿主切主题时仪表盘永远不变，用户会判定「跟随功能坏了」。规则：<strong>要给「跟随」留一条真正空着的路径</strong>，默认值不能拿一个具体预设充当。同类问题也适用于色盘、图例开关等所有「空 = 自动」的字段。</p><h2 id="九、收尾-机制-×-关键决策-×-失败模式" tabindex="-1"><a class="header-anchor" href="#九、收尾-机制-×-关键决策-×-失败模式"><span>九、收尾：机制 × 关键决策 × 失败模式</span></a></h2><table><thead><tr><th>机制</th><th>关键决策</th><th>对应失败模式</th></tr></thead><tbody><tr><td>schema 契约</td><td>可序列化、payload 黑盒、版本迁移在库内</td><td>schema 漂移、后端拒存</td></tr><tr><td>冗余列</td><td><code>chart_count</code> / <code>theme_key</code> 保存时从 schema 现算</td><td>客户端漏写导致列表元数据过期</td></tr><tr><td>数据链路</td><td>resolver 由宿主注入，<code>static</code> / <code>api</code> 两类数据集</td><td>无 resolver 静默空图（现为 fail-visible）</td></tr><tr><td>布局</td><td>自研 12 列网格，设计器/渲染器共用 <code>layoutCharts</code></td><td>图表 0 高度、缩放反馈环</td></tr><tr><td>渲染</td><td>引擎三方法 + 适配器注册表</td><td>未注册引擎白屏、CJS 预构建失败</td></tr><tr><td>设计器</td><td><code>commit</code> 快照 + 碰撞推挤 + 单卡槽剪贴板</td><td>撤销污染、图表重叠、粘贴错位</td></tr><tr><td>持久化</td><td><code>version</code> CAS + 保存前快照 + 可逆恢复</td><td>stale 覆盖、恢复不可逆</td></tr><tr><td>主题</td><td>空 <code>key</code> 跟随宿主，预设显式钉死</td><td>默认值钉死被当成跟随失效</td></tr></tbody></table><p>设计器的复杂度从来不在「把图画出来」，而在让<strong>设计态</strong>与<strong>运行态</strong>共享同一份可序列化的事实，再让宿主只在这份事实上做存取与并发控制。schema 是合同，resolver 是插座，version 是闸门——三者守住，画布可以随便换。</p><p>仓库（宿主与内核均可逐行核对）：</p><ul><li>宿主 GitHub：<a href="https://github.com/tx7do/go-wind-admin" target="_blank" rel="noopener noreferrer">github.com/tx7do/go-wind-admin</a></li><li>宿主 Gitee：<a href="https://gitee.com/tx7do/go-wind-admin" target="_blank" rel="noopener noreferrer">gitee.com/tx7do/go-wind-admin</a></li><li>设计器内核 GitHub：<a href="https://github.com/tx7do/go-wind-ui" target="_blank" rel="noopener noreferrer">github.com/tx7do/go-wind-ui</a>（<code>@go-wind/bi-core</code> / <code>bi-vue</code> / <code>bi-react</code>）</li></ul>`,112))])}const d=p(l,[["render",i]]),k=JSON.parse('{"path":"/posts/go-wind-admin-bi-dashboard-designer.html","title":"GoWind Admin 拆解：BI 大屏设计器——可序列化 schema、resolver 取数与版本快照","lang":"zh-CN","frontmatter":{"date":"2026-11-12T00:00:00.000Z","category":["GoWind风行"],"tag":["Golang","GoWind","BI","大屏","数据可视化"],"sticky":10},"headers":[{"level":2,"title":"一、边界：payload 是黑盒，宿主只负责存取","slug":"一、边界-payload-是黑盒-宿主只负责存取","link":"#一、边界-payload-是黑盒-宿主只负责存取","children":[]},{"level":2,"title":"二、schema：可序列化是硬约束，布局数学只写一份","slug":"二、schema-可序列化是硬约束-布局数学只写一份","link":"#二、schema-可序列化是硬约束-布局数学只写一份","children":[]},{"level":2,"title":"三、数据链路：resolver 是宿主的插座，transform 是内核的管线","slug":"三、数据链路-resolver-是宿主的插座-transform-是内核的管线","link":"#三、数据链路-resolver-是宿主的插座-transform-是内核的管线","children":[]},{"level":2,"title":"四、渲染链路：三个方法接一个引擎，主题在编译期落进 option","slug":"四、渲染链路-三个方法接一个引擎-主题在编译期落进-option","link":"#四、渲染链路-三个方法接一个引擎-主题在编译期落进-option","children":[]},{"level":2,"title":"五、设计器：框架无关的状态机，外面套两层 UI","slug":"五、设计器-框架无关的状态机-外面套两层-ui","link":"#五、设计器-框架无关的状态机-外面套两层-ui","children":[]},{"level":2,"title":"六、持久化：黑盒 payload、CAS 与可逆快照","slug":"六、持久化-黑盒-payload、cas-与可逆快照","link":"#六、持久化-黑盒-payload、cas-与可逆快照","children":[]},{"level":2,"title":"七、三端接入：同一心智模型，三种宿主形态","slug":"七、三端接入-同一心智模型-三种宿主形态","link":"#七、三端接入-同一心智模型-三种宿主形态","children":[]},{"level":2,"title":"八、失败模式：五类可复现的接入事故","slug":"八、失败模式-五类可复现的接入事故","link":"#八、失败模式-五类可复现的接入事故","children":[]},{"level":2,"title":"九、收尾：机制 × 关键决策 × 失败模式","slug":"九、收尾-机制-×-关键决策-×-失败模式","link":"#九、收尾-机制-×-关键决策-×-失败模式","children":[]}],"git":{"updatedTime":1794452832000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":2,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"afe7d090eeb42081261889c7bf8dbfa4f13403f4","time":1794452832000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: update posts."},{"hash":"3f2bb5b824398c26d07411b9460273dc1cab949d","time":1794367579000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-admin-bi-dashboard-designer.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>把可视化设计器接进中后台时，schema 如何同时约束设计器与渲染器、取数如何不焊死在图表组件里、整份覆盖保存又怎样避免互相踩踏？</strong></p>\\n</blockquote>\\n<p>BI 模块的产品形态可以压缩成一句话：一块可拖拽的仪表盘/大屏、一份描述它的 JSON，以及围绕这份 JSON 的存取与版本管理。真正难的不是把 ECharts 画出来，而是三条边界：</p>\\n<ul>\\n<li><strong>schema 与运行时</strong>：JSON 里不能有函数，取数与事件必须从外部注入；</li>\\n<li><strong>内核与宿主</strong>：图型、布局、主题、撤销栈归组件库，持久化、权限、租户归中后台；</li>\\n<li><strong>保存与并发</strong>：整份覆盖保存天然会互相踩踏，版本号与快照要把这条路收窄。</li>\\n</ul>"}');export{d as comp,k as data};
